import{at as e,it as t,n,vt as r}from"./chunks/framework.BZu6EPoN.js";var i=JSON.parse(`{"title":"Method for Calculating Available Capacity","description":"","frontmatter":{"title":"Method for Calculating Available Capacity","date":"2025-09-09","summary":"The total amount of user data a storage device can hold.","tags":["hardware"],"draft":false,"authors":["default"]},"headers":[],"relativePath":"blog/method-for-available-capacity.md","filePath":"en/blog/method-for-available-capacity.md"}`),a={name:`blog/method-for-available-capacity.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="hard-drive-available-capacity-calculation-method" tabindex="-1">Hard Drive Available Capacity Calculation Method <a class="header-anchor" href="#hard-drive-available-capacity-calculation-method" aria-label="Permalink to “Hard Drive Available Capacity Calculation Method”">​</a></h1><p>When purchasing or using hard drives (HDD, SSD, portable hard drives, USB flash drives, etc.), many users find that <strong>the actual usable capacity is often smaller than the capacity advertised by the manufacturer</strong>. This is not because the drive manufacturer is cutting corners, but because of differences in calculation methods and file systems. This article explains how to calculate the available capacity of a hard drive and why the &quot;capacity shrinkage&quot; phenomenon occurs.</p><p>The difference between utf8mb4 and utf8</p><h6 id="chatgpt-says" tabindex="-1">ChatGPT says: <a class="header-anchor" href="#chatgpt-says" aria-label="Permalink to “ChatGPT says:”">​</a></h6><p>Good question. This is actually a &quot;pitfall&quot; in MySQL.</p><hr><h2 id="_1-the-difference-between-utf8-and-utf8mb4-in-mysql" tabindex="-1">1. <strong>The difference between utf8 and utf8mb4 in MySQL</strong> <a class="header-anchor" href="#_1-the-difference-between-utf8-and-utf8mb4-in-mysql" aria-label="Permalink to “1. The difference between utf8 and utf8mb4 in MySQL”">​</a></h2><h3 id="mysql-s-utf8" tabindex="-1">MySQL&#39;s <code>utf8</code> <a class="header-anchor" href="#mysql-s-utf8" aria-label="Permalink to “MySQL&#39;s utf8”">​</a></h3><ul><li><strong>It is not standard UTF-8!</strong></li><li>It can only store UTF-8 characters of <strong>1–3 bytes</strong> (supporting at most Unicode U+FFFF, the BMP plane).</li><li>It cannot store <strong>4-byte characters</strong> (such as emoji, some special Chinese characters, minority scripts, and ancient scripts).</li><li>Examples: <ul><li><code>&quot;张&quot;</code> Can be stored</li><li><code>&quot;😀&quot;</code> Cannot be stored, and an error will be raised: <code>Incorrect string value</code></li></ul></li></ul><hr><h3 id="mysql-s-utf8mb4" tabindex="-1">MySQL&#39;s <code>utf8mb4</code> <a class="header-anchor" href="#mysql-s-utf8mb4" aria-label="Permalink to “MySQL&#39;s utf8mb4”">​</a></h3><ul><li>It is a <strong>truly complete UTF-8 implementation</strong> (supporting 1–4 bytes).</li><li>It can store all Unicode characters, including emoji.</li><li>It has been supported since MySQL 5.5.3.</li><li>It is recommended to <strong>use utf8mb4 consistently</strong> in new projects to avoid being unable to store emoji or other characters later.</li></ul><hr><h2 id="_2-storage-comparison" tabindex="-1">2. <strong>Storage comparison</strong> <a class="header-anchor" href="#_2-storage-comparison" aria-label="Permalink to “2. Storage comparison”">​</a></h2><table tabindex="0"><thead><tr><th>Character set</th><th>Max bytes per character</th><th>Emoji support</th><th>Notes</th></tr></thead><tbody><tr><td>utf8</td><td>3 bytes</td><td>No</td><td>MySQL&#39;s &quot;trimmed-down&quot; version of UTF-8</td></tr><tr><td>utf8mb4</td><td>4 bytes</td><td>Yes</td><td>The real UTF-8</td></tr></tbody></table><hr><h2 id="_3-performance-differences" tabindex="-1">3. <strong>Performance differences</strong> <a class="header-anchor" href="#_3-performance-differences" aria-label="Permalink to “3. Performance differences”">​</a></h2><ul><li>utf8mb4 has 1 extra byte of storage overhead compared with utf8, but the difference is very small.</li><li>In the vast majority of scenarios (especially web and mobile), utf8mb4 is recommended.</li></ul><hr><h2 id="_4-best-practices" tabindex="-1">4. <strong>Best practices</strong> <a class="header-anchor" href="#_4-best-practices" aria-label="Permalink to “4. Best practices”">​</a></h2><ol><li><p>Use utf8mb4 for <strong>databases, tables, and columns</strong></p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE DATABASE mydb DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;</span></span></code></pre></div></li><li><p><strong>Connection encoding</strong> must also be set to utf8mb4 (otherwise inserting emoji will still raise an error):</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SET NAMES utf8mb4;</span></span></code></pre></div></li><li><p>If a legacy database uses utf8, you can use:</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE mytable CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;</span></span></code></pre></div></li></ol><hr><p>Summary:</p><ul><li><code>utf8</code> = an incomplete UTF-8 that only supports 3 bytes</li><li><code>utf8mb4</code> = the real UTF-8 that supports 4 bytes, recommended at all times</li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};